int main(){char directory[]="/tmp/mgx-eff-restore-XXXXXX";assert(mkdtemp(directory) && !chdir(directory));DesktopFiles fs;assert(fs.directory("GROOVE") && fs.directory("PROJECTS"));auto p=std::make_unique<ProjectState>();make_empty_project(*p);p->tracks[0].instrument=Instrument::VirtualAnalog;p->tracks[0].virtual_analog.values[2]=9;auto e=std::make_unique<Engine>();assert(e->stage_project(*p));float pcm[2]{};e->render(pcm,0);auto ui=std::make_unique<Performance>(*e,*p);DesktopSampleAssets assets;assets.files(&fs);auto files=std::make_unique<SessionFiles>(fs,assets,*e,*p,*ui);files->project_locator("GROOVE/CURRENT.TXT");assert(files->remember_project("PROJECTS/original.mgxs"));auto original=std::make_unique<ProjectState>(*p);PreservedOwner original_store;assert(original_store && files->copy_preserved_to(*original_store));ChunkBuffer before;assert(encode_project_buffer(before,*p));WavView views[kSampleAssets]{};files->copy_bindings(views);auto other=std::make_unique<ProjectState>();make_empty_project(*other);other->tracks[0].instrument=Instrument::FM;{FileWriter file(fs,"PROJECTS/experiment.mgxs");assert(encode_project(file,*other) && file.finish());}assert(files->load("PROJECTS/experiment.mgxs",false,false));e->render(pcm,0);ui->poll();assert(p->tracks[0].instrument==Instrument::FM);char path[160];assert(read_project_location(fs,"GROOVE/CURRENT.TXT",path,sizeof path) && !__builtin_strcmp(path,"PROJECTS/original.mgxs"));assert(files->restore_probe_snapshot(*original,views,*original_store));e->render(pcm,0);ui->poll();ChunkBuffer after;assert(encode_project_buffer(after,*p) && before.size==after.size && !__builtin_memcmp(before.data,after.data,before.size));assert(p->tracks[0].instrument==Instrument::VirtualAnalog && p->tracks[0].virtual_analog.values[2]==9);puts("Efficiency snapshot: normal validated load without locator write, exact in-RAM content/ownership restoration passed");}
